+        to,
+        journal.targetId,
+        assetId,
+        stagingDir(target.directory, journal.moveId),
+        null,
+      );
+    }
+    await rm(journalPath(deps.journalDir, journal.moveId), { force: true });
+    throw error;
+  }
+}
