+  await writeFile(
+    join(meta, `${id}.json`),
+    JSON.stringify({
+      sidecarVersion: 2,
+      assetId,
+      title: "Demo take",
+      createdAt: 1_700_000_000_000,
+      derivedFromAssetId: null,
+      tagIds: tags.map((t) => t.id),
+      tagNames: tags.map((t) => t.name),
