+
+export interface HealReport {
+  /** Entries finished: rolled forward or back. */
+  healed: number;
+  /** Entries waiting for an unavailable workspace. */
+  waiting: number;
+  /** Entries kept and surfaced: neither side could be proven complete. */
+  quarantined: MoveJournal[];
